  const KIND_ICON = { mountain: '⛰️', plateau: '🏔️', plain: '🌾', basin: '🏺', river: '🛶', lake: '💧', sea: '🌊', island: '🏝️' };
  const KIND_COLOR = { mountain: '#7c5a40', plateau: '#8a6fae', plain: '#5f8f45', basin: '#a3683c', river: '#3b82c4', lake: '#3b9ec4', sea: '#2e6f9e', island: '#3a8f7a' };

