    $('gw-sun-play').addEventListener('click', () => { root.dispatchEvent(new CustomEvent('gm-world-sun-play')); clock.state().playing ? clock.pause() : clock.play(); });
    $('gw-sun-step').addEventListener('click', () => clock.setHour(clock.state().hour + 3));
